Here is a basic python example of how to perform a rainbow table lookup against a list of hashed passwords, using a pre-computed map of plaintext-to-hash pairs:

```python
import hashlib

# example of a simple pre-computed rainbow table (password -> md5 hash)
def generate_rainbow_table(wordlist):
    rainbow_table = {}
    for word in wordlist:
        hash_object = hashlib.md5(word.encode())
        hash_hexa = hash_object.hexdigest()
        rainbow_table[hash_hexa] = word
    return rainbow_table

# example of attacking a trove of hashed passwords
def rainbow_table_attack(hash_trove, rainbow_table):
    results = {}
    for hash in hash_trove:
        if hash in rainbow_table:
            results[hash] = rainbow_table[hash]
        else:
            results[hash] = "not found in table"
    return results

# example usage
if __name__ == "__main__":
    # sample wordlist for the table
    wordlist = ["password123", "admin", "let_me_in", "123456"]
    rainbow_table = generate_rainbow_table(wordlist)

    # trove of hashed passwords to reveal
    hash_trove = [
        "e10adc3949ba59abbe56e057f20f883e", # md5 for 123456
        "21232f297a57a5a743894a0e4a801fc3", # md5 for admin
        "v99z18x428xy38w5u260853678922v03"  # not in table
    ]

    results = rainbow_table_attack(hash_trove, rainbow_table)

    for hash, plaintext in results.items():
        print(f"hash: {hash} -> plaintext: {plaintext}")
